int handle_sysenter(struct x86_emulate_ctxt *ctxt) {
    unsigned long efer;

    /* Retrieve EFER MSR */
    if (!ctxt->ops->get_msr(ctxt, MSR_EFER, &efer))
        return X86EMUL_UNHANDLEABLE;

    /* Check for real mode */
    if ((efer & EFER_LMA) == 0) {
        return X86EMUL_CONTINUE;  // Real mode, inject general protection fault
    }

    /* Retrieve SYSENTER CS, EIP, and ESP MSRs */
    unsigned long cs, eip, esp;

    if (!ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip) ||
        !ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp)) {
        return X86EMUL_UNHANDLEABLE;
    }

    /* Set the context's instruction pointer and stack pointer */
    ctxt->regs->eip = eip;
    ctxt->regs->esp = esp;

    /* Set CS register */
    ctxt->regs->cs = cs;

    return X86EMUL_CONTINUE;
}

int emulate_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    // Retrieve the EFER MSR
    if (ctxt->ops->get_msr(ctxt, MSR_EFER, &efer) != 0)
        return X86EMUL_UNHANDLEDSIM;

    // Inject general protection fault if in real mode
    if ((efer & EFER_LMA) == 0)
        return X86EMUL_GPF;

    // Inject undefined instruction fault if in long mode
    if ((efer & EFER_LME) && (efer & EFER_LMA))
        return X86EMUL_UDF;

    uint64_t cs_msr, eip_msr, esp_msr;

    // Retrieve SYSENTER CS, EIP, and ESP MSRs
    if (ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs_msr) != 0 ||
        ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip_msr) != 0 ||
        ctxt->ops->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp_msr) != 0)
        return X86EMUL_UNHANDLEDSIM;

    // Update the context's registers
    ctxt->regs->cs = cs_msr;
    ctxt->regs->ip = eip_msr;
    ctxt->regs->sp = esp_msr;

    return X86EMUL_CONTINUE;
}

