    if (ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_CS, &cs) || ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_EIP, &eip) || ctxt->get_msr(ctxt, MSR_IA32_SYSENTER_ESP, &esp)) {
