int handle_sysenter(struct x86_emulate_ctxt *ctxt) {
    uint64_t efer;

    if (ctxt->mode == X86EMUL_MODE_REAL) {
        return inject_gp_fault(ctxt, 0);
    }

    efer = get_msr(ctxt, MSR_EFER);

    if ((efer & EFER_LMA) && (ctxt->mode != X86EMUL_MODE_PROT64)) {
        return inject_ud_fault(ctxt);
    }

    uint64_t sysenter_cs = get_msr(ctxt, MSR_IA32_SYSENTER_CS);
    uint64_t sysenter_esp = get_msr(ctxt, MSR_IA32_SYSENTER_ESP);
    uint64_t sysenter_eip = get_msr(ctxt, MSR_IA32_SYSENTER_EIP);

    if ((sysenter_cs & 3) != 3) {
        return inject_gp_fault(ctxt, 0);
    }

    if (ctxt->mode == X86EMUL_MODE_PROT64) {
        ctxt->regs->rax = sysenter_cs & 0xffff;
        ctxt->regs->rsp = sysenter_esp;
        ctxt->regs->rip = sysenter_eip;
        ctxt->eflags &= ~(X86_EFLAGS_VM);
    } else {
        ctxt->regs->cs = sysenter_cs;
        ctxt->regs->esp = sysenter_esp;
        ctxt->regs->eip = sysenter_eip;
        ctxt->eflags &= ~(X86_EFLAGS_VM);
    }

    return X86EMUL_CONTINUE;
}
